//! Terrain material adjacency table generated by the verified CD startup routine.
//! Pattern bytes are supplied by the reference-bound asset loader, not embedded.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BorderTableError { PatternLength { actual: usize } }
/// Generate the 4096 tile/orientation pairs from160 original four-corner patterns.
pub fn build(patterns: &[u8]) -> Result<[u8; 8192], BorderTableError> {
    if patterns.len() != 640 { return Err(BorderTableError::PatternLength { actual: patterns.len() }); }
    let mut table = [0u8; 8192];
    let mut assigned = [false; 4096];
    for pair in table.chunks_exact_mut(2) { pair[0] = 151; }
    for (tile, pattern) in patterns.chunks_exact(4).enumerate() {
        let [a,b,c,d] = [pattern[0]&7,pattern[1]&7,pattern[2]&7,pattern[3]&7];
        for (corners, orientation) in [([a,b,c,d],0),([b,a,d,c],16),([c,d,a,b],48),([d,c,b,a],32),([b,c,d,a],96),([c,b,a,d],112),([d,a,b,c],80),([a,d,c,b],64)] {
            let key = ((corners[0] as usize)<<9) | ((corners[1] as usize)<<6) | ((corners[2] as usize)<<3) | corners[3] as usize;
            if !assigned[key] { table[key*2] = tile as u8; table[key*2+1] = orientation; assigned[key] = true; }
        }
    }
    Ok(table)
}
